function isAnagram(s, t) {
  if (s.length !== t.length) return false;
  const sort = value => [...value].sort().join('');
  return sort(s) === sort(t);
}

advanced.code:
function isAnagram(s, t) {
  if (s.length !== t.length) return false;
  const count = new Map();
  for (const char of s) count.set(char, (count.get(char) ?? 0) + 1);
  for (const char of t) {
    const left = count.get(char) ?? 0;
    if (left === 0) return false;
    count.set(char, left - 1);
  }
  return true;
}

basic.code:
function isValid(s) {
  let previous;
  do {
    previous = s;
    s = s.replaceAll('()', '').replaceAll('[]', '').replaceAll('{}', '');
  } while (s !== previous);
  return s.length === 0;
}

advanced.code:
function isValid(s) {
  const stack = [];
  const match = { ')': '(', ']': '[', '}': '{' };
  for (const char of s) {
    if (!(char in match)) stack.push(char);
    else if (stack.pop() !== match[char]) return false;
  }
  return stack.length === 0;
}

