function merge(intervals) {
  const work = intervals.map(item => [...item]);
  let changed = true;
  while (changed) {
    changed = false;
    outer: for (let i = 0; i < work.length; i++) {
      for (let j = i + 1; j < work.length; j++) {
        if (work[i][0] <= work[j][1] && work[j][0] <= work[i][1]) {
          work[i] = [Math.min(work[i][0], work[j][0]), Math.max(work[i][1], work[j][1])];
          work.splice(j, 1); changed = true; break outer;
        }
      }
    }
  }
  return work;
}

