  let previous = null;
  let current = head;
  while (current) {
    const next = current.next;
    current.next = previous;
    previous = current;
    current = next;
  }
  return previous;
}

basic.code:
function mergeTwoLists(list1, list2) {
  const values = [];
  for (let node = list1; node; node = node.next) values.push(node.val);
  for (let node = list2; node; node = node.next) values.push(node.val);
  values.sort((a, b) => a - b);
  const dummy = { val: 0, next: null };
  let tail = dummy;
  for (const val of values) tail = tail.next = { val, next: null };
  return dummy.next;
}

