  let start = 0;
  while (start < queue.length) {
    const level = [];
    const levelEnd = queue.length;
    while (start < levelEnd) {
      const node = queue[start++];
      level.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    result.push(level);
  }
  return result;
}
